Объясни, как устроена и как работает эта программа целиком:

```python
import json

class Library:
    def __init__(self, path):
        self.path = path
        self.books = self._load()

    def _load(self):
        try:
            with open(self.path, encoding='utf-8') as f:
                return json.load(f)
        except FileNotFoundError:
            return {}

    def _save(self):
        with open(self.path, 'w', encoding='utf-8') as f:
            json.dump(self.books, f, ensure_ascii=False, indent=2)

    def add(self, isbn, title):
        self.books[isbn] = {'title': title, 'taken_by': None}
        self._save()

    def take(self, isbn, reader):
        book = self.books.get(isbn)
        if book is None or book['taken_by']:
            return False
        book['taken_by'] = reader
        self._save()
        return True

    def give_back(self, isbn):
        self.books[isbn]['taken_by'] = None
        self._save()

lib = Library('books.json')
lib.add('111', 'Мастер и Маргарита')
print(lib.take('111', 'Петя'), lib.take('111', 'Маша'))

```
